function itemTranslations(names: readonly string[]): ItemEntityTranslations {
  const legacyCount = ITEM_ENTITY_IDS.length - Object.keys(APPENDED_ITEM_NAMES).length;
  if (names.length !== ITEM_ENTITY_IDS.length && names.length !== legacyCount) {
    throw new Error(
      `Item translation count mismatch: expected ${legacyCount} or ${ITEM_ENTITY_IDS.length}, got ${names.length}`,
    );
  }
  const translations = {} as ItemEntityTranslations;
  const includesAppendedNames = names.length === ITEM_ENTITY_IDS.length;
  let sourceIndex = 0;
  ITEM_ENTITY_IDS.forEach((id, index) => {
    const name = includesAppendedNames
      ? names[index]
      : (APPENDED_ITEM_NAMES[id] ?? names[sourceIndex++]);
    if (!name) throw new Error(`Missing item translation for ${id}`);
    translations[id] = { name };
  });
  return translations;
}

function itemTranslationsEn(names: readonly string[]) {
  return {
    ...itemTranslations(names),
    conjured_water4: { name: 'Conjured Springwater' },
    conjured_bread4: { name: 'Conjured Feastloaf' },
    soul_stone: { name: 'Soul Stone' },
  };
}

